(function(sceditor) {
	"use strict";
	/**
	* Place holder GIF shown while image is loading.
	* @private
	*/
	const loadingGif = "data:image/gif;base64,";
	/**
	* Basic check for browser support
	* @private
	*/
	const isSupported = typeof window.FileReader !== "undefined";
	sceditor.plugins.dragdrop = function() {
		if (!isSupported) return;
		const base = this;
		let opts;
		let editor;
		let handleFile;
		let container;
		let cover;
		let placeholderId = 0;
		function hideCover() {
			cover.style.display = "none";
			container.className = container.className.replace(/(^| )dnd( |$)/g, "");
		}
		function showCover() {
			if (cover.style.display === "none") {
				cover.style.display = "block";
				container.className += " dnd";
			}
		}
		function isAllowed(_file) {
			return true;
		}
		function createHolder(toReplace) {
			const placeholder = document.createElement("img");
			placeholder.src = loadingGif;
			placeholder.className = "sceditor-ignore";
			placeholder.id = `sce-dragdrop-${placeholderId++}`;
			function replace(html) {
				const node = editor.getBody().ownerDocument.getElementById(placeholder.id);
				if (node) {
					if (typeof html === "string") node.insertAdjacentHTML("afterend", html);
					node.parentNode.removeChild(node);
				}
			}
			return function() {
				if (toReplace) toReplace.parentNode.replaceChild(placeholder, toReplace);
				else editor.wysiwygEditorInsertHtml(placeholder.outerHTML);
				return {
					insert: function(html) {
						replace(html);
					},
					cancel: replace
				};
			};
		}
		function handleDragOver(e) {
			const dt = e.dataTransfer;
			const files = dt.files.length || !dt.items ? dt.files : dt.items;
			for (let i = 0; i < files.length; i++) if (files[i].kind === "string") return;
			showCover();
			e.preventDefault();
		}
		function handleDrop(e) {
			const dt = e.dataTransfer;
			const files = dt.files.length || !dt.items ? dt.files : dt.items;
			hideCover();
			for (let i = 0; i < files.length; i++) {
				if (files[i].kind === "string") return;
				if (isAllowed(files[i])) handleFile(files[i], createHolder());
			}
			e.preventDefault();
		}
		base.signalReady = function() {
			editor = this;
			opts = editor.opts.dragdrop || {};
			handleFile = opts.handleFile;
			if (!handleFile) return;
			container = editor.getContentAreaContainer().parentNode;
			cover = container.appendChild(sceditor.dom.parseHTML(`<div class="sceditor-dnd-cover" style="display: none"></div>`).firstChild);
			container.addEventListener("dragover", handleDragOver);
			container.addEventListener("dragleave", hideCover);
			container.addEventListener("dragend", hideCover);
			container.addEventListener("drop", handleDrop);
			editor.getBody().addEventListener("dragover", handleDragOver);
			editor.getBody().addEventListener("drop", hideCover);
		};
		base.destroy = function() {
			if (!container) return;
			container.removeEventListener("dragover", handleDragOver);
			container.removeEventListener("dragleave", hideCover);
			container.removeEventListener("dragend", hideCover);
			container.removeEventListener("drop", handleDrop);
			editor.getBody().removeEventListener("dragover", handleDragOver);
			editor.getBody().removeEventListener("drop", hideCover);
			if (cover && cover.parentNode) cover.parentNode.removeChild(cover);
		};
		base.signalPasteHtml = function(file) {
			if (!file) return;
			if (!opts.handleFile) return;
			if (file.val) return;
			hideCover();
			if (!("handlePaste" in opts) || opts.handlePaste) {
				if (isAllowed(file)) handleFile(file, createHolder());
			}
		};
	};
})(sceditor);
//#endregion
